import { existsSync, readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { BRAND_VERSION, brandAssets } from "./brand-assets";

// brand-assets.ts is generated by `bun run brand`. These checks catch a hand edit or a
// half-committed run: every referenced file exists and carries the same version.
const local = (url: string) => `public${new URL(url, "https://mychata.cz").pathname}`;

describe("brand assets", () => {
  it("every referenced file exists in public/", () => {
    for (const [key, value] of Object.entries(brandAssets)) {
      if (typeof value !== "string") continue;
      expect(existsSync(local(value)), `${key}: ${value}`).toBe(true);
      expect(value, key).toContain(`?v=${BRAND_VERSION}`);
    }
  });

  it("the manifest uses the same icons", () => {
    const manifest = JSON.parse(readFileSync("public/manifest.webmanifest", "utf8"));
    const srcs = manifest.icons.map((i: { src: string }) => i.src);
    expect(srcs).toEqual([brandAssets.icon192, brandAssets.icon512]);
  });

  it("no Lovable icon or storage URL is referenced", () => {
    const root = readFileSync("src/routes/__root.tsx", "utf8");
    expect(root).not.toMatch(/r2\.dev|lovable\.(dev|app)\/.*\.(png|jpe?g|ico|svg)/);
  });
});
